import 'dart:convert' as convert;
import 'dart:io' as io;

import 'package:test/test.dart';

import 'package:unseal/unseal.dart';

import '../../support/opds2_corpus_expectation.dart';

import '../../support/opds2_shared_cases.dart';

/// Cross-checks the Dart parser against the pinned independent
/// expectations generated by the Python schema oracle
/// (jsonschema 4.25.1 + referencing 0.37.0, see
/// test/resources/opds/expected/ and doc/opds2.md).
///
/// The corpus itself — real catalogs, canonical spec examples, and
/// declared synthetic fixtures — is pinned by SHA-256 in
/// test/resources/opds/corpus-manifest.json.
void main() {
  final resources = io.Directory('test/resources/opds');
  final manifest =
      convert.jsonDecode(io.File('${resources.path}/corpus-manifest.json').readAsStringSync())
          as Map<String, Object?>;
  final feeds = (manifest['feeds']! as List<Object?>).cast<Map<String, Object?>>();

  group('corpus manifest integrity', () {
    test('every feed matches its pinned SHA-256', () {
      for (final row in feeds) {
        final bytes = io.File('${resources.path}/feeds/${row['name']}').readAsBytesSync();
        expect(
          sha256OfBytes(bytes),
          row['sha256'],
          reason:
              '${row['name']} changed; update corpus-manifest.json and provenance in the same commit',
        );
      }
    });
  });

  group('positive corpus matches the independent reference', () {
    for (final row in feeds) {
      if (row['kind'] != 'positive') continue;
      test('${row['name']} summarizes exactly as the Python reference', () {
        final source = io.File('${resources.path}/feeds/${row['name']}').readAsStringSync();
        final feed = parseOpds2Feed(source);
        final expected =
            convert.jsonDecode(
                  io.File(
                    '${resources.path}/expected/${row['name']}.expected.json',
                  ).readAsStringSync(),
                )
                as Map<Object?, Object?>;
        expect(summarizeFeed(feed, row['name']! as String), expected);
      });
    }
  });

  group('link fragments validate as template data', () {
    for (final row in feeds) {
      if (row['kind'] != 'link-positive') continue;
      test('${row['name']} keeps the search template as data', () {
        final source = io.File('${resources.path}/feeds/${row['name']}').readAsStringSync();
        final document = convert.jsonDecode(source) as Map<Object?, Object?>;
        expect(document['rel'], 'search');
        expect(document['templated'], isTrue);
        final href = document['href']! as String;
        final expanded = expandOpds2Template(href, {'query': 'verne'});
        expect(expanded, contains('?query='));
        expect(expanded.contains('{'), isFalse);
      });
    }
  });

  group('negative corpus fails typed, matching the schema reference', () {
    for (final row in feeds) {
      if (row['kind'] != 'negative') continue;
      test('${row['name']} is rejected with the expected failure', () {
        final source = io.File('${resources.path}/feeds/${row['name']}').readAsStringSync();
        try {
          parseOpds2Feed(source);
          fail('expected rejection');
        } on Opds2Exception catch (error) {
          expect(
            error.pointer,
            opds2ExpectedFailurePointers[row['name']],
            reason: '${row['name']}: ${error.message}',
          );
        }
      });
    }
  });

  group('normative-only corpus: schema accepts, the parser still refuses', () {
    for (final row in feeds) {
      if (row['kind'] != 'normative-only') continue;
      test('${row['name']} fails typed on the normative rule', () {
        final source = io.File('${resources.path}/feeds/${row['name']}').readAsStringSync();
        try {
          parseOpds2Feed(source);
          fail('expected rejection');
        } on Opds2Exception catch (error) {
          expect(error, isA<Opds2MalformedException>());
          expect(error.pointer, isNotNull);
        }
      });
    }
  });

  group('shared cases file matches the on-disk expectations', () {
    test('every embedded case equals its corpus fixture and pinned summary', () {
      final byName = <String, Map<String, Object?>>{
        for (final row in feeds)
          if (row['kind'] != 'link-positive') row['name']! as String: row,
      };
      expect(opds2SharedCases, hasLength(byName.length));
      for (final shared in opds2SharedCases) {
        final row = byName[shared.name];
        expect(row, isNotNull, reason: shared.name);
        expect(
          shared.source,
          io.File('${resources.path}/feeds/${shared.name}').readAsStringSync(),
          reason: shared.name,
        );
        expect(shared.kind, row!['kind'], reason: shared.name);
        final expectedPath = '${resources.path}/expected/${shared.name}.expected.json';
        if (shared.expectedSummaryJson == null) {
          expect(io.File(expectedPath).existsSync(), isFalse, reason: shared.name);
        } else {
          expect(
            shared.expectedSummaryJson,
            io.File(expectedPath).readAsStringSync(),
            reason: shared.name,
          );
        }
      }
    });
  });

  group('relative resolution matches the Python urljoin reference', () {
    final resolution =
        convert.jsonDecode(io.File('${resources.path}/expected/resolution.json').readAsStringSync())
            as Map<String, Object?>;
    for (final case_ in (resolution['cases']! as List<Object?>).cast<Map<String, Object?>>()) {
      test('"${case_['relative']}" against ${case_['base']}', () {
        final resolved = resolveOpds2Href(
          case_['relative']! as String,
          baseUrl: Uri.parse(case_['base']! as String),
        );
        expect(resolved.toString(), case_['expected']);
      });
    }
  });
}
